INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(11,'objectives','trueFalse · 1','1','{"section":"trueFalse","number":1,"text":"Two-dimensional motion occurs when an object moves only along the x-axis.","answer":false}'::jsonb,1,true),
(11,'objectives','trueFalse · 2','1','{"section":"trueFalse","number":2,"text":"The path of an object in two-dimensional motion is always a straight line.","answer":false}'::jsonb,2,true),
(11,'objectives','trueFalse · 3','1','{"section":"trueFalse","number":3,"text":"Average velocity is defined as total displacement per unit time.","answer":true}'::jsonb,3,true),
(11,'objectives','trueFalse · 4','1','{"section":"trueFalse","number":4,"text":"Instantaneous velocity is the rate of change of displacement with respect to time.","answer":true}'::jsonb,4,true),
(11,'objectives','trueFalse · 5','1','{"section":"trueFalse","number":5,"text":"An object moving with constant speed along a curved path is not accelerated.","answer":false}'::jsonb,5,true),
(11,'objectives','trueFalse · 6','1','{"section":"trueFalse","number":6,"text":"A projectile is any object thrown into space under the action of gravity alone.","answer":true}'::jsonb,6,true),
(11,'objectives','trueFalse · 7','1','{"section":"trueFalse","number":7,"text":"The path followed by a projectile is called a trajectory.","answer":true}'::jsonb,7,true),
(11,'objectives','trueFalse · 8','1','{"section":"trueFalse","number":8,"text":"In projectile motion, vertical velocity remains constant (ignoring air resistance).","answer":false}'::jsonb,8,true),
(11,'objectives','trueFalse · 9','1','{"section":"trueFalse","number":9,"text":"The maximum range of a projectile is obtained when projected at 45°.","answer":true}'::jsonb,9,true),
(11,'objectives','trueFalse · 10','1','{"section":"trueFalse","number":10,"text":"If a projectile is thrown horizontally, its initial vertical velocity is zero.","answer":true}'::jsonb,10,true),
(11,'objectives','trueFalse · 11','1','{"section":"trueFalse","number":11,"text":"The motion of water from a fountain is an example of projectile motion.","answer":true}'::jsonb,11,true),
(11,'objectives','trueFalse · 12','1','{"section":"trueFalse","number":12,"text":"Circular motion is a special type of one-dimensional motion.","answer":false}'::jsonb,12,true),
(11,'objectives','trueFalse · 13','1','{"section":"trueFalse","number":13,"text":"Circular motion is always accelerated motion.","answer":true}'::jsonb,13,true),
(11,'objectives','trueFalse · 14','1','{"section":"trueFalse","number":14,"text":"In circular motion, speed remains constant but velocity changes.","answer":true}'::jsonb,14,true),
(11,'objectives','trueFalse · 15','1','{"section":"trueFalse","number":15,"text":"Angular velocity is measured in rad s-2.","answer":false}'::jsonb,15,true),
(11,'objectives','trueFalse · 16','1','{"section":"trueFalse","number":16,"text":"If angular velocity is constant, angular acceleration is zero.","answer":true}'::jsonb,16,true),
(11,'objectives','trueFalse · 17','1','{"section":"trueFalse","number":17,"text":"Tangential speed is related to angular speed by v = rω.","answer":true}'::jsonb,17,true),
(11,'objectives','trueFalse · 18','1','{"section":"trueFalse","number":18,"text":"Linear velocity in circular motion is directed toward the centre.","answer":false}'::jsonb,18,true),
(11,'objectives','trueFalse · 19','1','{"section":"trueFalse","number":19,"text":"If angular displacement is zero, linear displacement must be zero.","answer":true}'::jsonb,19,true),
(11,'objectives','trueFalse · 20','1','{"section":"trueFalse","number":20,"text":"A bomb dropped from an airplane in horizontal flight has a curved trajectory.","answer":true}'::jsonb,20,true),
