(11,'objectives','trueFalse · 1','7','{"section":"trueFalse","number":1,"text":"Light is a mechanical wave.","answer":false}'::jsonb,1,true),
(11,'objectives','trueFalse · 2','7','{"section":"trueFalse","number":2,"text":"According to Newton, light consists of tiny particles called corpuscles.","answer":true}'::jsonb,2,true),
(11,'objectives','trueFalse · 3','7','{"section":"trueFalse","number":3,"text":"According to Newton, light travels as a wave.","answer":false}'::jsonb,3,true),
(11,'objectives','trueFalse · 4','7','{"section":"trueFalse","number":4,"text":"The interference of light can be explained by using corpuscular theory.","answer":false}'::jsonb,4,true),
(11,'objectives','trueFalse · 5','7','{"section":"trueFalse","number":5,"text":"Light travels faster in a denser medium.","answer":false}'::jsonb,5,true),
(11,'objectives','trueFalse · 6','7','{"section":"trueFalse","number":6,"text":"Refraction is the bending of light when it passes from one medium to another.","answer":true}'::jsonb,6,true),
(11,'objectives','trueFalse · 7','7','{"section":"trueFalse","number":7,"text":"Refraction occurs because the velocity of light changes in different media.","answer":true}'::jsonb,7,true),
(11,'objectives','trueFalse · 8','7','{"section":"trueFalse","number":8,"text":"Refraction of light can take place in a single medium.","answer":false}'::jsonb,8,true),
(11,'objectives','trueFalse · 9','7','{"section":"trueFalse","number":9,"text":"Refraction obeys two laws of reflection.","answer":false}'::jsonb,9,true),
(11,'objectives','trueFalse · 10','7','{"section":"trueFalse","number":10,"text":"The second law of refraction is known as Snell’s law.","answer":true}'::jsonb,10,true),
(11,'objectives','trueFalse · 11','7','{"section":"trueFalse","number":11,"text":"Snell’s law relates the sines of angles of incidence and reflection.","answer":false}'::jsonb,11,true),
(11,'objectives','trueFalse · 12','7','{"section":"trueFalse","number":12,"text":"No refraction occurs if light is incident normally on the surface.","answer":true}'::jsonb,12,true),
(11,'objectives','trueFalse · 13','7','{"section":"trueFalse","number":13,"text":"Light bends away from the normal when it enters a denser medium.","answer":false}'::jsonb,13,true),
(11,'objectives','trueFalse · 14','7','{"section":"trueFalse","number":14,"text":"The greater the refractive index, the smaller the bending of light.","answer":false}'::jsonb,14,true),
(11,'objectives','trueFalse · 15','7','{"section":"trueFalse","number":15,"text":"The refractive index between two media depends on the color of light.","answer":true}'::jsonb,15,true);
