(11,'objectives','fillBlank · 17','7','{"section":"fillBlank","number":17,"text":"The refractive index of air is approximately ________.","answer":["1"]}'::jsonb,37,true),
(11,'objectives','fillBlank · 18','7','{"section":"fillBlank","number":18,"text":"For red light, refractive index is ________ than for violet light.","answer":["smaller"]}'::jsonb,38,true),
