(11,'objectives','trueFalse · 1','8','{"section":"trueFalse","number":1,"text":"Lenses produce images by reflecting light.","answer":false}'::jsonb,1,true),
(11,'objectives','trueFalse · 2','8','{"section":"trueFalse","number":2,"text":"Refraction at a curved surface does not obey Snell’s law.","answer":true}'::jsonb,2,true),
(11,'objectives','trueFalse · 3','8','{"section":"trueFalse","number":3,"text":"The lens maker’s formula is derived from refraction at two spherical surfaces.","answer":true}'::jsonb,3,true),
(11,'objectives','trueFalse · 4','8','{"section":"trueFalse","number":4,"text":"In lens formula, all distances are measured from the optical center.","answer":true}'::jsonb,4,true),
(11,'objectives','trueFalse · 5','8','{"section":"trueFalse","number":5,"text":"For a real image, image distance is positive.","answer":true}'::jsonb,5,true),
(11,'objectives','trueFalse · 6','8','{"section":"trueFalse","number":6,"text":"A lens is a transparent optical device bounded by one or two curved surfaces.","answer":true}'::jsonb,6,true),
(11,'objectives','trueFalse · 7','8','{"section":"trueFalse","number":7,"text":"A convex lens is thicker at the edges than at the center.","answer":false}'::jsonb,7,true),
(11,'objectives','trueFalse · 8','8','{"section":"trueFalse","number":8,"text":"A concave lens is also called a converging lens.","answer":false}'::jsonb,8,true),
(11,'objectives','trueFalse · 9','8','{"section":"trueFalse","number":9,"text":"The principal axis of a lens passes through its optical center.","answer":true}'::jsonb,9,true),
(11,'objectives','trueFalse · 10','8','{"section":"trueFalse","number":10,"text":"The optical center of a lens lies in the middle of a symmetric lens on the principal axis.","answer":true}'::jsonb,10,true),
(11,'objectives','trueFalse · 11','8','{"section":"trueFalse","number":11,"text":"Rays passing through the optical center of a thin lens suffer no deviation.","answer":true}'::jsonb,11,true),
(11,'objectives','trueFalse · 12','8','{"section":"trueFalse","number":12,"text":"The principal focus of a convex lens is virtual.","answer":false}'::jsonb,12,true),
(11,'objectives','trueFalse · 13','8','{"section":"trueFalse","number":13,"text":"In calculation, the focal length of a concave lens is negative.","answer":true}'::jsonb,13,true),
(11,'objectives','trueFalse · 14','8','{"section":"trueFalse","number":14,"text":"When the object is at the principal focus F, the image is formed at infinity.","answer":true}'::jsonb,14,true),
(11,'objectives','trueFalse · 15','8','{"section":"trueFalse","number":15,"text":"The image formed by a concave lens is always on the same side as the object.","answer":true}'::jsonb,15,true),
(11,'objectives','trueFalse · 16','8','{"section":"trueFalse","number":16,"text":"The image produced by a concave lens is real and inverted.","answer":false}'::jsonb,16,true),
(11,'objectives','trueFalse · 17','8','{"section":"trueFalse","number":17,"text":"The image formed by a concave lens is always between F and p.","answer":true}'::jsonb,17,true),
(11,'objectives','trueFalse · 18','8','{"section":"trueFalse","number":18,"text":"For a convex lens, the focal length decreases if placed in water.","answer":true}'::jsonb,18,true),
(11,'objectives','trueFalse · 19','8','{"section":"trueFalse","number":19,"text":"A convex lens has positive power.","answer":true}'::jsonb,19,true),
(11,'objectives','trueFalse · 20','8','{"section":"trueFalse","number":20,"text":"A lens with a shorter focal length has greater power.","answer":true}'::jsonb,20,true);
