(11,'objectives','fillBlank · 6','12','{"section":"fillBlank","number":6,"text":"The wavelength of X-rays is ________ than that of visible light.","answer":["shorter"]}'::jsonb,26,true),
(11,'objectives','fillBlank · 7','12','{"section":"fillBlank","number":7,"text":"The wavelength of X-rays is ________ than that of gamma ray.","answer":["longer"]}'::jsonb,27,true),
(11,'objectives','fillBlank · 8','12','{"section":"fillBlank","number":8,"text":"The wavelength of X-rays is ________ than that of IR.","answer":["shorter"]}'::jsonb,28,true),
(11,'objectives','fillBlank · 9','12','{"section":"fillBlank","number":9,"text":"Each orbit of electron in an atom corresponds to a definite ________.","answer":["energy"]}'::jsonb,29,true),
(11,'objectives','fillBlank · 10','12','{"section":"fillBlank","number":10,"text":"Energy is ___ when an electron jumps from a lower orbit to a higher orbit.","answer":["absorbed"]}'::jsonb,30,true),
(11,'objectives','fillBlank · 11','12','{"section":"fillBlank","number":11,"text":"Energy is ___ when an electron jumps from a higher orbit to a lower orbit.","answer":["emitted"]}'::jsonb,31,true),
(11,'objectives','fillBlank · 12','12','{"section":"fillBlank","number":12,"text":"The energy of the nᵗʰ orbit in a hydrogen atom is ________.","answer":["−13.6","n² eV"]}'::jsonb,32,true),
(11,'objectives','fillBlank · 13','12','{"section":"fillBlank","number":13,"text":"Photoelectric effect is the emission of electrons when ________ falls on a metal surface.","answer":["light"]}'::jsonb,33,true),
(11,'objectives','fillBlank · 14','12','{"section":"fillBlank","number":14,"text":"The minimum frequency required to emit electrons is called the ________ frequency.","answer":["threshold"]}'::jsonb,34,true),
(11,'objectives','fillBlank · 15','12','{"section":"fillBlank","number":15,"text":"The energy of a photon with respect to frequency is given by E = ________.","answer":["hν"]}'::jsonb,35,true),
(11,'objectives','fillBlank · 16','12','{"section":"fillBlank","number":16,"text":"The photoelectric current depends on the ________ of light.","answer":["intensity"]}'::jsonb,36,true);
INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(11,'objectives','fillBlank · 17','12','{"section":"fillBlank","number":17,"text":"If the frequency is below ________ frequency, no electrons are emitted.","answer":["threshold"]}'::jsonb,37,true),
(11,'objectives','fillBlank · 18','12','{"section":"fillBlank","number":18,"text":"The particle nature of light is confirmed by the ________ effect.","answer":["photoelectric"]}'::jsonb,38,true),
(11,'objectives','fillBlank · 19','12','{"section":"fillBlank","number":19,"text":"The relation between photon energy and wavelength is E = ________.","answer":["hc","λ"]}'::jsonb,39,true),
(11,'objectives','fillBlank · 20','12','{"section":"fillBlank","number":20,"text":"The speed of a photon is equal to the speed of ________.","answer":["light"]}'::jsonb,40,true),
(11,'objectives','fillBlank · 21','12','{"section":"fillBlank","number":21,"text":"A photon has ________ rest mass.","answer":["zero"]}'::jsonb,41,true),
(11,'objectives','fillBlank · 22','12','{"section":"fillBlank","number":22,"text":"Isotopes are atoms of the same element having different numbers of ____.","answer":["neutrons"]}'::jsonb,42,true),
(11,'objectives','fillBlank · 23','12','{"section":"fillBlank","number":23,"text":"Isotopes have the same ________ number.","answer":["atomic"]}'::jsonb,43,true),
(11,'objectives','fillBlank · 24','12','{"section":"fillBlank","number":24,"text":"Isotopes differ in their ________ number.","answer":["mass"]}'::jsonb,44,true),
